/* VAT, inventory age, owner funding and investment planning surfaces. */
for(const [a,d] of Object.entries({仮払消費税等:'課税仕入・設備・課税経費の支払時に分けた消費税。決算時に仮受分と精算します。',仮受消費税等:'課税売上で受け取る消費税。カード代金の入金前でも売上時に計上します。',未払消費税等:'決算で確定した消費税納付額。原則、決算２か月後の５月に納付します。',未収消費税等:'決算で確定した消費税還付額。ゲームでは２か月後に入金します。',仮払消費税中間納付:'前年の消費税額に基づく中間納付。決算の確定額から差し引きます。',商品廃棄損:'期限切れ・陳腐化・活きアジ死亡による在庫の廃棄原価です。廃棄時は預金を再び減らしません。',役員借入金:'社長個人が会社に貸した返済期限なしの資金。B/Sでは負債、ゲームの銀行審査では自己資本に加算します。'}))descriptions[a]=d;
const rawOrderCost=orderCost;orderCost=()=>E.gross(state,rawOrderCost());
const oldOrders=renderOrders;renderOrders=function(){oldOrders();const net=rawOrderCost(),tax=orderCost()-net;el('orderTotal').innerHTML=`${yen(orderCost())}<small>税込（税抜 ${yen(net)} ＋ 消費税 ${yen(tax)}）</small>`;};
const oldStockDetail=stockDetail;stockDetail=function(i){oldStockDetail(i);const p=E.PRODUCTS[i];const life=p.life||p.obsolete;el('shopDialogBody').innerHTML+=`<h3>仕入月と在庫の年齢</h3><p>金額は税抜。支払・販売代金には消費税10％が加算されます。</p><table class="age-table"><thead><tr><th>仕入月</th><th>数量</th><th>廃棄まで</th></tr></thead><tbody>${state.lots[i].map(l=>`<tr><td>${fy(l.turn)}期 ${month(l.turn)}月</td><td>${l.quantity}${p.unit}</td><td>${life?Math.max(0,life-(state.turn-l.turn))+'か月':'毎月5％死亡'}</td></tr>`).join('')}</tbody></table>`;};
const oldTutorial=renderTutorial;renderTutorial=function(){oldTutorial();el('tutorialPlanning').innerHTML+=`<details><summary>消費税と廃棄損のルール</summary><p>資本金1,000万円の課税事業者・税抜経理。商品・設備・店舗経費は税抜表示、現金支払と売掛金は税込です。給与・社会保険・利息・返還される敷金・借入には消費税を加算しません。仕入先は適格請求書発行事業者、税率10％・全額控除を前提とした概算です。</p><p>３月に精算、５月に納付／還付（還付時期はゲーム設定）。前年度の国税相当額48万円超で中間納付。資金計画にも含めます。軽減税率・簡易課税・申告端数等は省略。</p><p>常温エサ６か月、冷凍エサ３か月で期限切れ。仕掛け18・竿24・ルアー12・リール30か月で陳腐化廃棄（ゲーム設定）。古い仕入分から売れます。</p>${state.vatStartTurn?'<p>旧セーブは移行後の取引から消費税を記録します。過去決算は変更しません。</p>':''}</details>`;};
const oldPersonalV19=renderPersonal;renderPersonal=function(){oldPersonalV19();el('personalStatus').textContent+=` 役員借入金 ${fmt(state.balances.役員借入金||0)}。銀行審査では役員借入金を自己資本に加算、役員貸付金を資産・利益から損失補正します。`;};
function showOwnerFunding(){openShop('社長から会社へ貸す',`<p>個人預金 ${fmt(state.owner)} ／ 会社預金 ${fmt(cash())}</p><p>借方：預金 ／ 貸方：役員借入金。利益は増えません。返済期限なし・無利息のゲーム設定で、銀行は自己資本に加算します。生活費の余裕を残してください。</p><label>貸す金額（円）<input id="ownerFundingAmount" type="number" min="1000" step="1000" max="${Math.max(0,state.owner)}" value="${Math.max(0,Math.floor(Math.max(0,state.owner-120000)/1000)*1000)}"></label><button id="confirmOwnerFunding" ${state.closed||state.ended?'disabled':''}>この金額を会社へ貸す</button>`);}
const originalBankEvidence=bankEvidence;bankEvidence=function(a){return `<div class="bank-adjustment"><h3>銀行審査用の補正（帳簿は変更しない）</h3><p>帳簿純資産 ${fmt(a.bookEquity||0)} ＋ 役員借入金 ${fmt(a.ownerDebt||0)} − 役員貸付金 ${fmt(a.ownerLoss||0)} ＝ 審査用自己資本 ${fmt(a.adjustedEquity||0)}</p><p>利益にも役員貸付金残高 ${fmt(a.ownerLoss||0)} の損失相当額を反映。補正後経常利益 ${fmt(a.adjustedOrdinary||0)}。返済力を過大評価しないためのゲーム審査ルールです。</p></div>`+originalBankEvidence(a);};
let investmentPlan={equipment:'freezer',loan:0,rate:5,term:60,delay:0,hire:'none',months:12,price:'list',effort:'quarterly'};
let planResult=null;
function showInvestmentPlan(id){if(id)investmentPlan.equipment=id;const dialog=el('investmentPlanner');renderInvestmentPlan();if(!dialog.open)dialog.showModal();el('closeInvestmentPlanner').focus();}
function renderInvestmentPlan(){const p=investmentPlan;el('investmentPlanControls').innerHTML=`<label>設備<select data-plan="equipment"><option value="none" ${p.equipment==='none'?'selected':''}>投資なし</option>${Object.entries(E.EQUIPMENT).map(([id,x])=>`<option value="${id}" ${p.equipment===id?'selected':''}>${x.name}${state.equipment[id]?'（購入済み）':''}</option>`).join('')}</select></label><label>投資時期<select data-plan="delay">${[0,3,6,9].map(n=>`<option value="${n}" ${p.delay===n?'selected':''}>${n===0?'今月':n+'か月後'}</option>`).join('')}</select></label><label>試算期間<select data-plan="months">${[12,24].map(n=>`<option ${p.months===n?'selected':''}>${n}</option>`).join('')}</select>か月</label><label>借入予定額（円）<input data-plan="loan" type="number" min="0" max="10000000" step="10000" value="${p.loan}"></label><label>年利（％）<input data-plan="rate" type="number" min="0.1" max="20" step="0.1" value="${p.rate}"></label><label>返済月数<input data-plan="term" type="number" min="12" max="120" step="12" value="${p.term}"></label><label>投資の翌月以降、募集可能月に採用（人物未指定の標準能力で試算）<select data-plan="hire">${[['none','採用なし'],...Object.entries(E.ROLES).filter(([id])=>id!=='que').map(([id,x])=>[id,x.name])].map(([id,name])=>`<option value="${id}" ${p.hire===id?'selected':''}>${name}</option>`).join('')}</select></label><label>販売価格<select data-plan="price">${[['list','定価'],['plus10','10％値上げ'],['minus10','10％値引き'],['sale','毎月セール']].map(([id,name])=>`<option value="${id}" ${p.price===id?'selected':''}>${name}</option>`).join('')}</select></label><label>営業努力<select data-plan="effort"><option value="quarterly" ${p.effort==='quarterly'?'selected':''}>11月・２月に改善</option><option value="none" ${p.effort==='none'?'selected':''}>店番のみ</option></select></label>`;calculateInvestmentPlan();}
function calculateInvestmentPlan(){const p=investmentPlan;planResult=InvestmentPlanner.compare(state,p);const format=r=>r.error?`<p class="negative">${r.error}</p>`:`<p>実際の試算期間：${r.rows.length}か月（希望 ${r.requestedMonths}か月）</p>${r.status==='horizon'?'<p>120か月の経営終了までを試算しています。</p>':''}<dl><dt>期間損益</dt><dd>${fmt(r.profit)}</dd><dt>最低月末預金</dt><dd class="${r.minimumCash<0?'negative':''}">${fmt(r.minimumCash)}</dd><dt>最終預金</dt><dd>${fmt(r.endCash)}</dd></dl>${r.ended?'<p class="negative">支払不能で計算終了</p>':''}`;
 const cards=[['baseline','設備だけ追加しない'],['investment','計画を実施する'],['downside','計画・需要15％減']];const rowCount=Math.max(planResult.baseline.rows.length,planResult.investment.rows.length,planResult.downside.rows.length),timeline=Array.from({length:rowCount},(_,i)=>planResult.baseline.rows[i]||planResult.investment.rows[i]||planResult.downside.rows[i]);
 el('investmentPlanResults').innerHTML=`<div class="plan-cards">${cards.map(([k,name])=>`<section><h3>${name}</h3>${format(planResult[k])}</section>`).join('')}</div><p>「設備だけ追加しない」は、採用・価格・営業努力を計画案とそろえ、設備と借入の差だけを比較します。季節・集客の減衰・営業努力の遅れ・税込仕入・廃棄・減価償却・返済・納税を反映。仕入れは毎月推奨量。基準ケースの需要変動は固定、下振れケースは全月15％減。試算中はバイトを自動登用せず、４年の退職期限を反映します。融資の成立や売上を保証するものではありません。</p><div class="plan-table-scroll"><table><thead><tr><th>月</th><th>投資なし預金</th><th>投資後預金</th><th>下振れ預金</th><th>投資後損益</th><th>在庫</th><th>廃棄損</th><th>元利返済</th><th>納税／還付</th></tr></thead><tbody>${timeline.map((basis,i)=>{const b=planResult.baseline.rows[i],r=planResult.investment.rows[i],d=planResult.downside.rows[i];return `<tr><th>${fy(basis.turn)}期${month(basis.turn)}月</th><td>${b?amountText(b.cash):'終了'}</td><td>${r?amountText(r.cash):'—'}</td><td>${d?amountText(d.cash):'—'}</td><td>${r?amountText(r.profit):'—'}</td><td>${r?amountText(r.inventory):'—'}</td><td>${r?amountText(r.waste):'—'}</td><td>${r?amountText(r.repayment+r.interest):'—'}</td><td>${r?amountText(r.tax)+'／'+amountText(r.refund):'—'}</td></tr>`;}).join('')}</tbody></table></div><p>単位：千円。設備借入期間は設備の償却期間以内。予定借入は仮定です。将来の投資は自動予約されません。${p.delay>0?'実行予定月になったら、最新の資金と審査条件でもう一度試算してください。':'下のボタンは今月の購入・融資条件を改めて確認します。融資は銀行で別途審査し、条件が変われば自動で再試算します。'}</p><button id="planToDecision" ${planResult.investment.status==='invalidPlan'||p.equipment==='none'||p.delay>0||state.closed||state.ended||state.equipment[p.equipment]?'disabled':''}>${p.delay>0?'将来月の投資は予約できません':'試算を終えて今月の投資判断へ'}</button>`;
}
const previousInvestments=showInvestments;showInvestments=function(){previousInvestments();el('shopDialogBody').innerHTML='<button data-open-plan="true">先に投資計画をシミュレーション</button>'+el('shopDialogBody').innerHTML;};
const previousPreviewBuy=previewBuy;previewBuy=function(id){previousPreviewBuy(id);el('shopDialogBody').innerHTML='<button data-plan-equipment="'+id+'">この設備で先にシミュレーション</button>'+el('shopDialogBody').innerHTML;};
document.addEventListener('change',e=>{const key=e.target.dataset?.plan;if(!key)return;let v=e.target.value;if(['loan','rate','term','months','delay'].includes(key)){v=Number(v);if(!Number.isFinite(v))return;const bounds={loan:[0,10000000],rate:[.1,20],term:[12,120],months:[12,24],delay:[0,9]};v=Math.max(bounds[key][0],Math.min(bounds[key][1],v));if(key!=='rate')v=Math.round(v);e.target.value=String(v);}investmentPlan[key]=v;calculateInvestmentPlan();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='openInvestmentPlanner'||b.dataset.openPlan||b.dataset.planEquipment){showInvestmentPlan(b.dataset.planEquipment);}else if(b.id==='closeInvestmentPlanner'){el('investmentPlanner').close();}else if(b.id==='planToDecision'){el('investmentPlanner').close();if(investmentPlan.loan>0){bankPlanAssumptions=structuredClone(investmentPlan);bankPurpose=investmentPlan.equipment;requestBankLoan(investmentPlan.loan);}else previewBuy(investmentPlan.equipment);}else if(b.id==='ownerFundingMenu'){showOwnerFunding();}else if(b.id==='confirmOwnerFunding'){try{state=E.lendByOwner(state,Number(el('ownerFundingAmount').value));closeShop();renderPlanning();saveGame();toast('個人預金から会社へ貸しました。役員借入金を計上しました。');}catch(err){toast(err.message);}}});
renderPlanning();
for(const [id,label] of [['openInvestmentPlanner','投資計画'],['ownerFundingMenu','社長から貸す']]){const button=document.createElement('button');button.id=id;button.className='help-top';button.textContent=label;document.querySelector('.top').append(button);}
const oldTransactionVAT=transactionView;transactionView=function(e){const html=oldTransactionVAT(e);return e.introVAT?html.replace('<div class="entry-arrow"',`<p class="vat-entry">あわせて 仮払消費税等／預金 ${fmt(e.introVAT)}。支払総額 ${fmt(e.amount+e.introVAT)}。下のB/Sには両方を反映。</p><div class="entry-arrow"`):html;};

const beforeAssortmentOverview=renderOverview;renderOverview=function(){beforeAssortmentOverview();const a=E.assortmentStatus(state);el('shopOverview').innerHTML+=`<p class="inventory-hint"><b>現在の品揃え ${a.stocked}／${a.total}種類</b> · 自然減を${Math.round(a.ratio*100)}％抑制。月末も全種類の在庫があれば集客力の自然減ゼロ。売切れ・廃棄後の在庫で判定し、未解放商品は対象外です。</p>`;};renderPlanning();

function productEconomics(i,forecast){const p=E.PRODUCTS[i],unit=p.price*(p.fixedPrice?1:({list:1,plus10:1.1,minus10:.9,sale:.8}[choice.price]||1)),margin=(unit-p.cost)/unit,r=forecast?.products?.[i];return `<div class="product-economics"><span>税抜売価 <b>${yen(unit)}</b></span><span>粗利率 <b>${(margin*100).toFixed(1)}％</b></span><span>月間売上見込み <b>${r?fmt(r.sales):'—'}</b></span><span>見込み粗利 <b>${r?fmt(r.grossProfit):'—'}</b>${r?' · '+r.quantity+p.unit:''}</span></div>`;}
const beforeEconomicsOrders=renderOrders;renderOrders=function(){beforeEconomicsOrders();const f=E.forecast(state,choice.quantities,choice.price,currentAction());document.querySelectorAll('.product-order').forEach(card=>{const input=card.querySelector('input[data-product]');if(input)card.insertAdjacentHTML('beforeend',productEconomics(Number(input.dataset.product),f));});el('orders').insertAdjacentHTML('afterbegin','<p class="inventory-hint">粗利率＝（税抜売価−仕入単価）÷税抜売価。売上見込みは現在の仕入数量・価格・行動・季節・集客・接客上限を反映した１か月分（需要変動なし）。家賃・給与・廃棄損を引く前の利益です。入力不備・月確定後は見込みを表示しません。</p>');};
const beforeEconomicsDetail=stockDetail;stockDetail=function(i){beforeEconomicsDetail(i);el('shopDialogBody').innerHTML+=`<h3>現在の販売方針での採算</h3>${productEconomics(i,E.forecast(state,choice.quantities,choice.price,currentAction()))}<p>見込みは税抜・値引き反映済み。売上と入金時期は異なり、カード代金は２か月後に入金します。</p>`;};
const beforeRetiredTutorial=renderTutorial;renderTutorial=function(){beforeRetiredTutorial();if(state.inventory[7]>0)el('tutorialPlanning').innerHTML+='<p>商品整理：旧ウェア在庫は次の月次処理で原価返品し、預金へ戻します。返品の仕訳を残し、利益は変えません。</p>';};
renderPlanning();
